package com.shopsphere.dao;
import com.shopsphere.model.Category;
import com.shopsphere.util.DBConnection;
import java.sql.*;
import java.util.*;
public class CategoryDAO {
    public Category findById(Integer id) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM categories WHERE id=?")) { p.setInt(1, id); try (ResultSet r = p.executeQuery()) { return r.next() ? map(r) : null; } } catch (SQLException e) { return null; } }
    public Category findBySlug(String slug) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM categories WHERE slug=?")) { p.setString(1, slug); try (ResultSet r = p.executeQuery()) { return r.next() ? map(r) : null; } } catch (SQLException e) { return null; } }
    public List<Category> findAllActive() { List<Category> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM categories WHERE status='ACTIVE' ORDER BY name"); ResultSet r = p.executeQuery()) { while (r.next()) l.add(map(r)); } catch (SQLException e) {} return l; }
    public List<Category> findAllWithProductCount() { List<Category> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT c.*, COUNT(p.id) AS prod_count FROM categories c LEFT JOIN products p ON c.id=p.category_id GROUP BY c.id ORDER BY c.id"); ResultSet r = p.executeQuery()) { while (r.next()) { Category cat = map(r); cat.setProductCount(r.getInt("prod_count")); l.add(cat); } } catch (SQLException e) {} return l; }
    public boolean create(Category cat) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("INSERT INTO categories (name,slug,description,image_url,status) VALUES (?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) { p.setString(1, cat.getName()); p.setString(2, cat.getSlug()); p.setString(3, cat.getDescription()); p.setString(4, cat.getImageUrl()); p.setString(5, cat.getStatus().name()); if (p.executeUpdate() > 0) { try (ResultSet k = p.getGeneratedKeys()) { if (k.next()) cat.setId(k.getInt(1)); } return true; } } catch (SQLException e) {} return false; }
    public boolean update(Category cat) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("UPDATE categories SET name=?,slug=?,description=?,image_url=?,status=? WHERE id=?")) { p.setString(1, cat.getName()); p.setString(2, cat.getSlug()); p.setString(3, cat.getDescription()); p.setString(4, cat.getImageUrl()); p.setString(5, cat.getStatus().name()); p.setInt(6, cat.getId()); return p.executeUpdate() > 0; } catch (SQLException e) {} return false; }
    public boolean delete(Integer id) { try (Connection c = DBConnection.getConnection()) { try (PreparedStatement ch = c.prepareStatement("SELECT COUNT(*) FROM products WHERE category_id=?")) { ch.setInt(1, id); try (ResultSet r = ch.executeQuery()) { if (r.next() && r.getInt(1) > 0) return false; } } try (PreparedStatement d = c.prepareStatement("DELETE FROM categories WHERE id=?")) { d.setInt(1, id); return d.executeUpdate() > 0; } } catch (SQLException e) {} return false; }
    public int countTotalCategories() { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT COUNT(*) FROM categories"); ResultSet r = p.executeQuery()) { if (r.next()) return r.getInt(1); } catch (SQLException e) {} return 0; }
    private Category map(ResultSet r) throws SQLException { Category cat = new Category(); cat.setId(r.getInt("id")); cat.setName(r.getString("name")); cat.setSlug(r.getString("slug")); cat.setDescription(r.getString("description")); cat.setImageUrl(r.getString("image_url")); cat.setStatus(Category.Status.valueOf(r.getString("status"))); cat.setCreatedAt(r.getTimestamp("created_at")); return cat; }
}
